# ---------------------------------------------------------------------------------------------------------------------
# METRICS SERVER
# ---------------------------------------------------------------------------------------------------------------------
locals {
  otel_collector_enabled = (
    var.otel_collector_enabled != null
    ? var.otel_collector_enabled
    : lookup(var.otel_collector_enabled_cluster_types, local.cluster_type, true)
  )
}

# OTEL Collector
module "otel_collector" {
  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/monitoring/otel-collector.git?ref=v1.0.7"
  count  = local.otel_collector_enabled ? 1 : 0

  providers = {
    kubernetes = kubernetes.local-cluster
    helm       = helm.local-cluster
  }

  chart_version           = var.otel_collector_version
  otellb_image            = var.otel_lb_image
  otel_image              = var.otel_image
  otel_lb_replicas        = var.otel_lb_replicas
  otel_collector_replicas = var.otel_collector_replicas
  image_tag_version       = var.otel_collector_image_tag
}

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------
variable "otel_collector_version" {
  description = "Version of otel-collector helm chart"
  type        = string
  default     = ""
  validation {
    condition     = var.otel_collector_version == "" && local.otel_collector_enabled ? false : true
    error_message = "otel_collector_version must be set when otel_collector is enabled"
  }
}

variable "otel_collector_image_tag" {
  description = "Version of otel-collector image tag"
  type        = string
  default     = ""
  validation {
    condition     = var.otel_collector_image_tag == "" && local.otel_collector_enabled ? false : true
    error_message = "otel_collector_image_tag must be set when otel_collector is enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "otel_collector_enabled_cluster_types" {
  description = "Types of clusters otel_collector should be enabled on by default"
  type        = map(string)
  default = {
    "mgmt"  = true
    "cps"   = true
    "saas"  = true
    "infra" = false
    "dev"   = false
  }
}

variable "otel_collector_enabled" {
  description = "Override for explicitly enabling or disabling otel-collector"
  type        = bool
  default     = null
}

variable "otel_lb_image" {
  description = "image for the otel collector loadbalancer"
  type        = string
  default     = "registry.ic-ops.net/cache-docker-hub/otel/opentelemetry-collector-contrib"
}

variable "otel_image" {
  description = "image for the otel collector/processor"
  type        = string
  default     = "registry.ic-ops.net/cache-docker-hub/otel/opentelemetry-collector-contrib"
}

variable "otel_lb_replicas" {
  description = "number of replicas for the otel loadbalancer to have"
  type        = number
  default     = 3
}

variable "otel_collector_replicas" {
  description = "number of replicas for the otel collector/processor to have"
  type        = number
  default     = 3
}

variable "otel_collector_additional_config" {
  description = "Alternate helm chart config to be used (overwrites entire helm config, does not merge)"
  type        = any
  default     = null
}

# ---------------------------------------------------------------------------------------------------------------------
# APPLICATION DEPLOYMENT
# ---------------------------------------------------------------------------------------------------------------------
locals {
  application_deployment_enabled = (
    var.application_deployment_enabled != null
    ? var.application_deployment_enabled
    : lookup(var.application_deployment_enabled_cluster_types, local.cluster_type, true)
  )
  application_deployment_repo_url = (
    var.application_deployment_repo_url != ""
    ? var.application_deployment_repo_url
    : lookup(
      local.app_deploy_repo,
      local.cluster_type,
      "ssh://git@gitlab.infrastructure.immuta.io:22/infrastructure/kubernetes/application-deployment.git"
    )
  )
  application_deployment_github_repo_url = (
    var.application_deployment_github_repo_url != ""
    ? var.application_deployment_repo_url
    : lookup(
      local.app_deploy_repo_github,
      local.cluster_type,
      "ssh://git@github.com:22/immuta/application-deployment.git"
    )
  )
}

module "application_deployment" {
  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/compute/application-deployment.git?ref=v2.1.0"
  count  = local.application_deployment_enabled ? 1 : 0

  providers = {
    kubernetes = kubernetes.local-cluster
  }

  vault_endpoint = var.vault_endpoint
  cluster_name   = var.cluster_name

  external_secrets_vault_secret_name        = var.external_secrets_vault_secret_name
  external_secrets_cluster_store_vault_path = var.external_secrets_cluster_store_vault_path
  application_deployment_repo_url           = local.application_deployment_repo_url
  application_deployment_github_repo_url    = local.application_deployment_github_repo_url
  application_deployment_branch             = var.application_deployment_branch
  application_deployment_refresh_interval   = var.application_deployment_refresh_interval
  application_deployment_prune              = var.application_deployment_prune

  depends_on = [
    module.cilium,
    module.fluxcd,
    module.external_secrets
  ]
}

data "external" "application_deployment_validate" {
  count = local.application_deployment_enabled && !(local.fluxcd_enabled || local.external_secrets_enabled) ? 1 : 0

  program = ["Error: application_deployment can only be set if fluxcd and external-secrets are enabled as well"]
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables are configurable, but have reasonable defaults set.
# ---------------------------------------------------------------------------------------------------------------------
variable "application_deployment_enabled_cluster_types" {
  description = "Types of clusters that application-deployment should be enabled on by default"
  type        = map(bool)
  default = {
    "mgmt"  = true
    "cps"   = true
    "saas"  = true
    "infra" = true
    "dev"   = true
  }
}

variable "application_deployment_enabled" {
  description = "Override for explicitly enabling or disabling application-deployment"
  type        = bool
  default     = null
}

variable "application_deployment_repo_url" {
  description = "Repo URL for application-deployment"
  type        = string
  default     = ""
}

variable "application_deployment_github_repo_url" {
  description = "Repo URL for application-deployment in GitHub"
  type        = string
  default     = ""
}

variable "application_deployment_branch" {
  description = "branch on application-deployment repo to reference"
  type        = string
  default     = "master"
}

variable "application_deployment_refresh_interval" {
  description = "Golang timestring for how often the target branch should be synced"
  type        = string
  default     = "1m0s"
}

variable "application_deployment_prune" {
  description = "Determines if resources removed from the application-deployment Git Repo will also be deleted by flux"
  type        = bool
  default     = true
}

